# FT call-again, fictitious log reset, MSK144 ping duration.
KEYS.update({
    'ftrestart_action': _t('FT: call the DX again when he is decoded', 'FT: richiama il DX quando viene decodificato', "FT : rappeler le DX quand il est décodé", 'FT: DX erneut rufen, wenn er dekodiert wird', 'FT: kall opp DX igjen når han dekodes', 'FT: znovu volat DX, když je dekódován'),
    'ftrestart_tip': _t('When the TX has stopped (no answer, STOP) and the DX call is decoded again as the sender, TX starts again with the selected message for him, in the opposite period. Not with RR73/73/RRR or CQ, at most 3 times per call (TX resets the count), not with the SWR block.',
                        "Quando la TX si è fermata (nessuna risposta, STOP) e il nominativo DX viene decodificato di nuovo come stazione che trasmette, la TX riparte con il messaggio selezionato per lui, nel periodo opposto. Non con RR73/73/RRR o CQ, al massimo 3 volte per nominativo (TX azzera il conteggio), non con il blocco ROS.",
                        "Quand l'émission s'est arrêtée (pas de réponse, STOP) et que l'indicatif DX est décodé à nouveau comme émetteur, l'émission reprend avec le message sélectionné pour lui, dans la période opposée. Pas avec RR73/73/RRR ou CQ, au plus 3 fois par indicatif (TX remet le compte à zéro), pas avec le blocage ROS.",
                        'Wenn TX gestoppt hat (keine Antwort, STOP) und das DX-Rufzeichen erneut als Sender dekodiert wird, startet TX wieder mit der für ihn gewählten Nachricht in der Gegenperiode. Nicht bei RR73/73/RRR oder CQ, höchstens 3-mal pro Rufzeichen (TX setzt den Zähler zurück), nicht bei SWR-Sperre.',
                        'Når TX har stoppet (ikke svar, STOP) og DX-kallesignalet dekodes igjen som avsender, starter TX igjen med valgt melding til ham i motsatt periode. Ikke med RR73/73/RRR eller CQ, høyst 3 ganger per kallesignal (TX nullstiller tellingen), ikke med SWR-sperre.',
                        'Když se TX zastavilo (bez odpovědi, STOP) a DX značka je znovu dekódována jako vysílající, TX začne znovu s vybranou zprávou pro něj v opačné periodě. Ne s RR73/73/RRR nebo CQ, nejvýše 3krát na značku (TX vynuluje počet), ne s blokováním PSV.'),
    'logreset_menu': _t('Fictitious log reset...', 'Reset fittizio del log...', 'Remise à zéro fictive du log...', 'Fiktiver Log-Neustart...', 'Fiktiv nullstilling av loggen...', 'Fiktivní vynulování deníku...'),
    'logreset_title': _t('Fictitious log reset', 'Reset fittizio del log', 'Remise à zéro fictive du log', 'Fiktiver Log-Neustart', 'Fiktiv nullstilling av loggen', 'Fiktivní vynulování deníku'),
    'logreset_tip': _t('QSOs before a UTC time are ignored for worked-before calls, new countries and new squares. The logbook is not changed.',
                       "I QSO prima di un'ora UTC non contano per nominativi già collegati, nuovi paesi e nuovi quadrati. Il log non viene modificato.",
                       "Les QSO avant une heure UTC sont ignorés pour les indicatifs déjà contactés, les nouveaux pays et les nouveaux carrés. Le log n'est pas modifié.",
                       'QSOs vor einer UTC-Zeit zählen nicht für bereits gearbeitete Rufzeichen, neue Länder und neue Felder. Das Log wird nicht verändert.',
                       'QSO-er før et UTC-tidspunkt teller ikke for allerede kjørte kallesignaler, nye land og nye ruter. Loggen endres ikke.',
                       'Spojení před časem UTC se nepočítají pro již navázané značky, nové země a nové čtverce. Deník se nemění.'),
    'logreset_info': _t('QSOs logged before this time (UTC) are ignored for worked-before calls, new countries, new squares and the needed-station marks, as if the log started here. The logbook is not changed: maps, statistics and exports still use every QSO. Useful for a new activity, a contest weekend or a new antenna.',
                        "I QSO registrati prima di quest'ora (UTC) non contano per nominativi già collegati, nuovi paesi, nuovi quadrati e segni delle stazioni che servono, come se il log cominciasse qui. Il log non viene modificato: mappe, statistiche ed esportazioni usano ancora tutti i QSO. Utile per una nuova attività, un weekend di contest o una nuova antenna.",
                        "Les QSO enregistrés avant cette heure (UTC) sont ignorés pour les indicatifs déjà contactés, les nouveaux pays, les nouveaux carrés et les marques des stations utiles, comme si le log commençait ici. Le log n'est pas modifié : cartes, statistiques et exports utilisent toujours tous les QSO. Utile pour une nouvelle activité, un week-end de contest ou une nouvelle antenne.",
                        'Vor dieser Zeit (UTC) geloggte QSOs zählen nicht für bereits gearbeitete Rufzeichen, neue Länder, neue Felder und die Markierung benötigter Stationen, als ob das Log hier begänne. Das Log wird nicht verändert: Karten, Statistiken und Exporte nutzen weiter alle QSOs. Nützlich für eine neue Aktivität, ein Contest-Wochenende oder eine neue Antenne.',
                        'QSO-er logget før dette tidspunktet (UTC) teller ikke for allerede kjørte kallesignaler, nye land, nye ruter og merking av ønskede stasjoner, som om loggen begynte her. Loggen endres ikke: kart, statistikk og eksport bruker fortsatt alle QSO-er. Nyttig for en ny aktivitet, en contest-helg eller en ny antenne.',
                        'Spojení zapsaná před tímto časem (UTC) se nepočítají pro již navázané značky, nové země, nové čtverce a označení potřebných stanic, jako by deník začínal zde. Deník se nemění: mapy, statistiky a exporty dál používají všechna spojení. Užitečné pro novou aktivitu, závodní víkend nebo novou anténu.'),
    'logreset_enable': _t('Ignore the QSOs before', 'Ignora i QSO prima del', 'Ignorer les QSO avant le', 'QSOs ignorieren vor', 'Ignorer QSO-er før', 'Ignorovat spojení před'),
    'logreset_now': _t('Now', 'Adesso', 'Maintenant', 'Jetzt', 'Nå', 'Nyní'),
    'msk_ping_ms_tip': _t('Ping duration in ms (20 ms steps): how long the MSK144 band stayed 3 dB above the noise of the period around the decoded frame.',
                          'Durata del ping in ms (passi di 20 ms): per quanto la banda MSK144 è rimasta 3 dB sopra il rumore del periodo attorno al frame decodificato.',
                          'Durée du ping en ms (pas de 20 ms) : combien de temps la bande MSK144 est restée 3 dB au-dessus du bruit de la période autour de la trame décodée.',
                          'Ping-Dauer in ms (20-ms-Schritte): wie lange das MSK144-Band um den dekodierten Rahmen 3 dB über dem Rauschen der Periode blieb.',
                          'Ping-varighet i ms (trinn på 20 ms): hvor lenge MSK144-båndet lå 3 dB over støyen i perioden rundt den dekodede rammen.',
                          'Délka pingu v ms (kroky 20 ms): jak dlouho bylo pásmo MSK144 kolem dekódovaného rámce 3 dB nad šumem periody.'),
})

# Split Operation for MSK144 and Q65 too (WSJT-X/JTDX style), RigControlSettingsDialog / mainwindow.
KEYS.update({
    'text.ft4_ft8_msk144_and_q65_keep_tx_audio_between_1500_and_2000_hz_moving_the_tx_dial_in_500_hz': _t(
        'FT4/FT8, MSK144 and Q65: keep TX audio between 1500 and 2000 Hz, moving the TX dial in 500 Hz steps (WSJT-X/JTDX). Rig uses separate RX/TX VFOs; Fake It (default) temporarily retunes a single VFO at each TX/RX transition. Without CAT there is no split.',
        "FT4/FT8, MSK144 e Q65: mantiene l'audio TX tra 1500 e 2000 Hz spostando la frequenza TX a passi di 500 Hz (come WSJT-X/JTDX). Rig usa VFO RX/TX separati; Fake It (di serie) risintonizza temporaneamente un singolo VFO a ogni transizione TX/RX. Senza CAT non c'è split.",
        "FT4/FT8, MSK144 et Q65 : maintient l'audio TX entre 1500 et 2000 Hz en déplaçant la fréquence TX par pas de 500 Hz (WSJT-X/JTDX). Rig utilise des VFO RX/TX séparés ; Fake It (par défaut) réaccorde temporairement un seul VFO à chaque transition TX/RX. Sans CAT, pas de split.",
        'FT4/FT8, MSK144 und Q65: Hält das TX-Audio zwischen 1500 und 2000 Hz und verschiebt die TX-Frequenz in 500-Hz-Schritten (WSJT-X/JTDX). Rig verwendet getrennte RX/TX-VFOs; Fake It (Standard) stimmt bei jedem TX/RX-Wechsel vorübergehend einen einzelnen VFO um. Ohne CAT kein Split.',
        'FT4/FT8, MSK144 og Q65: holder TX-lyden mellom 1500 og 2000 Hz og flytter TX-frekvensen i steg på 500 Hz (WSJT-X/JTDX). Rig bruker separate RX/TX-VFO-er; Fake It (standard) stiller midlertidig om én VFO ved hver TX/RX-overgang. Uten CAT brukes ikke split.',
        'FT4/FT8, MSK144 a Q65: udržuje TX audio mezi 1500 a 2000 Hz a posouvá TX kmitočet v krocích po 500 Hz (WSJT-X/JTDX). Rig používá oddělené RX/TX VFO; Fake It (výchozí) dočasně přelaďuje jeden VFO při každém přechodu TX/RX. Bez CAT se split nepoužije.'),
    'log.tx_aborted_cat_split_preparation_failed_or_timed_out': _t(
        'TX aborted: CAT split preparation failed or timed out.',
        'TX annullata: la preparazione dello split via CAT non è riuscita o è scaduta.',
        'TX annulée : la préparation du split par CAT a échoué ou a expiré.',
        'TX abgebrochen: Die Split-Vorbereitung über CAT ist fehlgeschlagen oder abgelaufen.',
        'TX avbrutt: split-forberedelsen via CAT feilet eller fikk tidsavbrudd.',
        'TX zrušeno: příprava splitu přes CAT selhala nebo vypršel čas.'),
})
